#!/bin/bash
# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #
#
# This file is set up to run a Veracode SCA scan on the core of {Your Project}.
# See https://help.veracode.com/r/yWEmzLVoSzK6HlP~GSch2w/aQFdmZoIqjHrYuZEbN2QTQ for complete documentation.
#
# The overall algorithm is this.
# 1) Check if a authorization token is configured (SRCCLR_API_TOKEN).
# 2) Run the SCA agent scanner against the source directory (SRC_DIR).
#
# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #

# Exit if any step fails
set -e
# Log each command line
set -x

# Check if python3 is installed, if not install it
if ! [ -x "$(command -v python3)" ]; then
	echo "python3 could not be found, installing..."
	apk add --no-cache python3
fi

# # Check if .npmrc is configured correctly & dependencies come from internal artifactory.
# # Get the current directory of the script and run the registry-check.py script assuming
# # that the script is in the same directory as this shell script.
# SCRIPT_PATH="$(realpath "${BASH_SOURCE[0]}")"
# echo "SCRIPT_PATH: ${SCRIPT_PATH}"
# SCRIPT_DIR="$(dirname "$SCRIPT_PATH")"
# echo "SCRIPT_DIR: ${SCRIPT_DIR}"
# python3 ${SCRIPT_DIR}/registry-check.py --root .

# This variable defines the directory where the dependency management files are stored
if [ -z $SRCCLR_BASEDIR ]; then
    SRCCLR_BASEDIR="."
fi

if [ -z $SRCCLR_API_TOKEN ]; then
	echo "---> ERROR: SRCCLR_API_TOKEN not set, aborting."
	exit 254;
fi

# Required because of recent SCA scan errors
export DISABLE_FIPS=true

# Allow quick (only look at package-lock/yarn.lock) and dirty (uncommitted changes)
curl -sSL https://download.sourceclear.com/ci.sh | sh -s -- scan --allow-dirty --quick